// Parse Geert's JSON response
const response = items[0].json.response;

// Extract JSON from response (might have markdown code blocks)
let jsonText = response;
if (response.includes('```json')) {
  const match = response.match(/```json\n([\s\S]*?)\n```/);
  if (match) jsonText = match[1];
} else if (response.includes('```')) {
  const match = response.match(/```\n([\s\S]*?)\n```/);
  if (match) jsonText = match[1];
}

try {
  const parsed = JSON.parse(jsonText);
  return [{
    json: {
      epic: parsed,
      project_name: items[0].json.project_name,
      sprint_duration_weeks: items[0].json.sprint_duration_weeks
    }
  }];
} catch (e) {
  // Fallback: return raw response for debugging
  return [{
    json: {
      error: 'Failed to parse JSON',
      raw_response: response,
      project_name: items[0].json.project_name
    }
  }];
}

// Parse Saskia's sprint plan
const response = items[0].json.response;

let jsonText = response;
if (response.includes('```json')) {
  const match = response.match(/```json\n([\s\S]*?)\n```/);
  if (match) jsonText = match[1];
} else if (response.includes('```')) {
  const match = response.match(/```\n([\s\S]*?)\n```/);
  if (match) jsonText = match[1];
}

const sprint = JSON.parse(jsonText);

return [{
  json: {
    sprint_plan: sprint,
    epic: items[0].json.epic,
    project_name: items[0].json.project_name
  }
}];

// Create individual task entries
const sprintId = items[0].json.id;
const tasks = items[0].json.sprint_plan.tasks;

// Return array of tasks to insert
return tasks.map((task, index) => ({
  json: {
    sprint_id: sprintId,
    agent_name: task.assigned_to,
    activity_type: 'task_assignment',
    description: `${task.title}: ${task.description}`,
    status: 'assigned',
    metadata: JSON.stringify({
      story_id: task.story_id,
      task_id: task.task_id,
      story_points: task.story_points,
      dependencies: task.dependencies,
      order: task.order
    })
  }
}));

// Aggregate all results for response
const sprint = items[0].json.sprint_plan;
const sprintId = items[0].json.id;
const epic = items[0].json.epic;

return [{
  json: {
    success: true,
    sprint_id: sprintId,
    sprint_name: sprint.sprint_name,
    sprint_goal: sprint.sprint_goal,
    total_story_points: sprint.total_story_points,
    user_stories_count: epic.user_stories.length,
    tasks_count: sprint.tasks.length,
    assignments: sprint.tasks.map(t => ({
      agent: t.assigned_to,
      task: t.title,
      points: t.story_points
    })),
    next_step: 'Tasks assigned. Agents will be notified via Workflow 2.',
    webhook_url: 'http://n8n:5678/webhook/council/task/start'
  }
}];
